using Clary.Api.Identity;
using Clary.Api;using Npgsql;using Xunit;
public class InventoryDocumentationTests{
 [Fact]public async Task LinkingIsIdempotentAndPreservesProseAndRevisions(){var schema="inventory_doc_"+Guid.NewGuid().ToString("N");await using var admin=NpgsqlDataSource.Create(Environment.GetEnvironmentVariable("CLARY_TEST_CONNECTION")!);await using(var q=admin.CreateCommand($"CREATE SCHEMA {schema}"))await q.ExecuteNonQueryAsync();try{await using var db=NpgsqlDataSource.Create(new NpgsqlConnectionStringBuilder(Environment.GetEnvironmentVariable("CLARY_TEST_CONNECTION")!){SearchPath=schema+",public"}.ConnectionString);await using(var q=db.CreateCommand(await File.ReadAllTextAsync(Path.Combine(AppContext.BaseDirectory,"database","001-initial.sql"))))await q.ExecuteNonQueryAsync();await FixtureCompany.MigrateAsync(db);var service=new InventoryDocumentation(db);var library=new LibraryRepository(db);var root=await library.CreateAsync(FixtureCompany.Context,"Inventory",null,default);var folder=await library.CreateAsync(FixtureCompany.Context,"Computers",root.Id,default);var original=await new LibraryOperations(db).NewPageAsync(FixtureCompany.Context,new("Computers","Original instructions",folder.Id),default);var pending=await service.LinkAsync(FixtureCompany.Context,null,false,default);Assert.Null(pending.DocumentId);Assert.Equal(original.Id,Assert.Single(pending.Candidates).Id);Assert.Equal("Original instructions",(await new LibraryOperations(db).ContentAsync(FixtureCompany.Context,original.Id,default))??"Original instructions");
  var linked=await service.LinkAsync(FixtureCompany.Context,original.Id,false,default);Assert.NotNull(linked.DocumentId);Assert.Equal(linked.DocumentId,(await service.LinkAsync(FixtureCompany.Context,null,false,default)).DocumentId);var operations=new LibraryOperations(db);var content=await operations.ContentAsync(FixtureCompany.Context,linked.DocumentId!.Value,default);Assert.Contains("inventory",content!);Assert.Contains("Original instructions",content!);Assert.NotEqual(original.Id,linked.DocumentId);Assert.DoesNotContain("192.168",RichDocument.Read(content!).Text);var revised=await operations.EditAsync(FixtureCompany.Context,linked.DocumentId.Value,new("Computer inventory","",null,"[{\"type\":\"p\",\"children\":[{\"type\":\"text\",\"text\":\"Keep this instruction\"}]},{\"type\":\"inventory\",\"category\":\"Computer\"}]"),default);Assert.Equal(revised.Id,(await service.GetAsync(FixtureCompany.Context,default)).DocumentId);Assert.Contains("Keep this instruction",(await operations.ContentAsync(FixtureCompany.Context,revised.Id,default))!);Assert.Throws<ArgumentException>(()=>RichDocument.Read("[{\"type\":\"inventory\",\"category\":\"Secret\"}]"));
 }finally{await using var q=admin.CreateCommand($"DROP SCHEMA {schema} CASCADE");await q.ExecuteNonQueryAsync();}}
}


